class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        sums = {0}
        for v in coins:
            sums |= {s + v for s in sums}
        r = 0
        while r + 1 in sums:
            r += 1
        return r + 1

c.cpp:
class Solution {
public:
    int getMaximumConsecutive(vector<int>& coins) {
        unordered_set<long long> sums;
        sums.insert(0);
        for (int v : coins) {
            vector<long long> add;
            for (long long s : sums) add.push_back(s + v);
            sums.insert(add.begin(), add.end());
        }
        long long r = 0;
        while (sums.count(r + 1)) ++r;
        return (int)(r + 1);
    }
};

c.java:
class Solution {
    public int getMaximumConsecutive(int[] coins) {
        Set<Long> sums = new HashSet<>();
        sums.add(0L);
        for (int v : coins) {
            List<Long> add = new ArrayList<>();
            for (long s : sums) add.add(s + v);
            sums.addAll(add);
        }
        long r = 0;
        while (sums.contains(r + 1)) r++;
        return (int) (r + 1);
    }
}

c.javascript:
var getMaximumConsecutive = function(coins) {
    const sums = new Set([0]);
    for (const v of coins) {
        const add = [...sums].map(s => s + v);
        for (const s of add) sums.add(s);
    }
    let r = 0;
    while (sums.has(r + 1)) r++;
    return r + 1;
};

