class Solution {
public:
    int getMaximumConsecutive(vector<int>& coins) {
        sort(coins.begin(), coins.end());
        long long reach = 0;
        for (int v : coins) {
            if (v > reach + 1) break;
            reach += v;
        }
        return (int)(reach + 1);
    }
};

